import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/quesion_imgs_32617d3c40374baf9093aba7cf6d02f8.Bhf8NXSu.png",e="/bzygq/assets/quesion_imgs_17e163055e7a477ba8550fd89bb6e2ba.7dzSU55V.png",p="/bzygq/assets/quesion_imgs_4f8328e4062e4074afe7ff7bde650070.BrL0RqRC.png",i="/bzygq/assets/quesion_imgs_ccf7ea16820e49a291ee8ac2bc2380cd.CaGvxbCX.png",g="/bzygq/assets/quesion_imgs_db252cd7cdc34d19b06d1af8a975c539.BvKpagwT.png",_="/bzygq/assets/quesion_imgs_6c49d5dfe93646c09b23f20449db979f.DcOPs20D.png",c="/bzygq/assets/quesion_imgs_244e42e9e4394d94b5aa19d58a52a950.CgSB7h5W.png",l="/bzygq/assets/quesion_imgs_a11dab00ab7044479ebb8b7b3a1f5910.Bn4Wx2qs.png",d="/bzygq/assets/quesion_imgs_bac00a581d9c4fbab4f4d98b8375016e.GeBn_a0I.png",y=JSON.parse('{"title":"6. 图形叠加","description":"","frontmatter":{},"headers":[],"relativePath":"行测/逻辑推理/1.图形推理/6. 图形叠加.md","filePath":"行测/逻辑推理/1.图形推理/6. 图形叠加.md","lastUpdated":1788883925000}'),m={name:"行测/逻辑推理/1.图形推理/6. 图形叠加.md"};function b(h,s,u,f,q,B){return a(),r("div",null,[...s[0]||(s[0]=[o('<h1 id="_6-图形叠加" tabindex="-1">6. 图形叠加 <a class="header-anchor" href="#_6-图形叠加" aria-label="Permalink to &quot;6. 图形叠加&quot;">​</a></h1><p>行测中的“叠加”题型主要考察的是考生对图形重叠后产生的规律性变化的理解和识别能力。这类题目通常会给出一组图形，要求考生根据图形的叠加规律找出答案。下面我将从几个方面系统地介绍这一题型：</p><h1 id="叠加的定义" tabindex="-1">叠加的定义 <a class="header-anchor" href="#叠加的定义" aria-label="Permalink to &quot;叠加的定义&quot;">​</a></h1><p>指两个或多个图形重叠在一起后，根据一定的规则产生新的图形。</p><p><img src="'+n+'" alt=""></p><p>1、 <strong>去同存异</strong>：两个图形重叠后，相同的部分消失，不同的部分保留。</p><p><img src="'+e+'" alt=""></p><p>2、 <strong>去异求同</strong>：两个图形重叠后，不同的部分消失，相同的部分保留。</p><p><img src="'+p+'" alt=""></p><p>3、 <strong>简单叠加</strong>：给出多个图形，要求找出它们重叠后的结果，直接将两个图形重叠在一起，根据叠加规则得出结果。</p><h1 id="常见考法" tabindex="-1">常见考法 <a class="header-anchor" href="#常见考法" aria-label="Permalink to &quot;常见考法&quot;">​</a></h1><p>1、 <strong>简单叠加</strong>：给出多个图形，要求找出它们重叠后的结果，直接将两个图形重叠在一起，根据叠加规则得出结果。</p><p><img src="'+i+'" alt=""></p><p>2、 <strong>叠加后旋转</strong>：给出多个图形，要求先将它们重叠，然后再旋转，先将两个图形重叠，根据叠加规则得出结果，然后再将结果图形旋转一定角度。 3、 <strong>先旋转后叠加</strong>：给出多个图形，要求先将它们旋转，然后再重叠，先将两个图形分别旋转一定角度，然后再将它们重叠，根据叠加规则得出结果。</p><p><img src="'+g+'" alt=""></p><p>4、 <strong>按行或按列</strong>：给出一个3×3九宫格或三+三形式的图形，要求按行或按列进行叠加，逐行或逐列进行叠加，根据叠加规则得出每一行或每一列的结果，最后综合得出整个九宫格或三+三形式的结果。</p><h2 id="解题策略" tabindex="-1">解题策略 <a class="header-anchor" href="#解题策略" aria-label="Permalink to &quot;解题策略&quot;">​</a></h2><p><strong>观察细节</strong>：</p><ul><li><strong>图形形状</strong>：观察每个图形的形状，判断它们重叠后的变化。</li><li><strong>颜色</strong>：观察每个图形的颜色，判断它们重叠后的变化。</li><li><strong>位置</strong>：观察每个图形的位置，判断它们重叠后的变化。</li></ul><p><strong>寻找规律</strong>：</p><ul><li><strong>叠加规则</strong>：明确叠加的规则，如去同存异或去异求同。</li><li><strong>旋转方向</strong>：如果涉及旋转，注意旋转的方向和角度。</li><li><strong>顺序</strong>：如果涉及多个步骤，注意操作的顺序，如先旋转后叠加或先叠加后旋转。</li></ul><p><strong>排除法</strong>：</p><ul><li><strong>排除明显不符合的选项</strong>：先排除那些与题目要求明显不符的选项。</li><li><strong>逐步缩小范围</strong>：通过逐步排除，最终找到符合要求的选项。</li></ul><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><p><strong>例1：从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</strong></p><p><img src="'+_+'" alt=""></p><p>解析：考查图形的简单叠加；九宫格优先按行看，图1叠加图2后，全保留得到图3，验证第2行满足题意，第三行叠加后选A。</p><p><strong>例2：请从所给的四个选项中，选出最恰当的一项填入问号处，使之呈现一定的规律性。</strong></p><p><img src="'+c+'" alt=""></p><p>解析：考查旋转后叠加，去同存异。图形内部元素大部分相同，<a href="https://zhida.zhihu.com/search?content_id=234984840&amp;content_type=Article&amp;match_order=1&amp;q=%E4%B9%9D%E5%AE%AB%E6%A0%BC%E5%9B%BE%E5%BD%A2&amp;zhida_source=entity" target="_blank" rel="noreferrer">九宫格图形</a>优先按行看，第一行图1逆时针旋转90度，叠加图2，去同存异，验证第二行满足，所以第三行图1逆时针旋转90度，叠加图2，去同存异，得到A选项。</p><p><strong>例3：从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</strong></p><p><img src="'+l+'" alt=""></p><p>解析：考查旋转+叠加后留同；观察第一组图，图形外轮廓基本一致，存在相似部分，图2旋转180度，叠加图1得到图3，第二组图2旋转180度，叠加图1得到图3，选D。</p><p><strong>例4：从所给的四个选项中选择最合适的一个填入问号处，使之呈现一定的规律：</strong></p><p><img src="'+d+'" alt=""></p><p>解析：考查列方向的叠加；图形间有相似的线条。九宫格优先按行看，并没有发现规律，再考虑按列看，通过观察发现，每一列图2与图3相加得到图1，故第三列图3还缺中间一条竖线和一条长横线，包括这两条线的只有D项。故正确答案为D。</p>',36)])])}const x=t(m,[["render",b]]);export{y as __pageData,x as default};
